/**
 * 1.3.8 (QA V137-7): the open-source licence list generated by scripts/gen-licenses.js from the
 * production dependency tree in node_modules (transitive, deduplicated by name@version, with the full
 * licence text where the package ships one; identical texts stored once).
 */
export type LicensePackage = { name: string; version: string; license: string; repository: string | null; homepage?: string | null; text: number | null };
export type LicenseData = { generatedFrom?: string; packages: LicensePackage[]; texts: string[] };

/** Case-insensitive match on package name or licence id (e.g. "apache"). Empty query = all. */
export function filterLicenses(packages: LicensePackage[], query: string): LicensePackage[] {
  const q = query.trim().toLowerCase();
  if (!q) return packages;
  return packages.filter((p) => p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q));
}

export function licenseText(data: LicenseData, p: LicensePackage): string | null {
  return p.text === null || p.text === undefined ? null : (data.texts[p.text] ?? null);
}
